SourceCode.Declaration:
internal abstract class GUPBasePriceCalcBase
{
    protected ItemId              itemId;
    protected InventDimId         inventDimId;
    protected InventDim           inventDim;
    protected UnitOfMeasureSymbol inventUnitId;

    protected TransDate           calcDate;
    protected Qty                 seriesSize;

    protected LineNum             lineNum;
    protected LineNum             globalLineNum;

    protected Map                 mapTotalItemConsumption; // used for calculation trade agreements
    protected boolean             existTradeAgreements;

    protected boolean             useStandardQty;

    protected RunbaseProgress     progressBar;
    protected boolean             showProgress;
    protected int64               progressTotals;

    protected NoYes               overrideGroupWarnings;

    protected boolean             skipInventTablevalidation;
    private const int   infiniteLoopThreshold = 100;

}

Method.Source:
private LineNum getLineNum()
{
    LineNum newLineNum;

    globalLineNum++;
    newLineNum = globalLineNum;

    return newLineNum;
}

protected void incProgressTotals()
{
    if (!progressBar)
    {
        return;
    }

    progressTotals++;
}

protected void initParameters()
{
    InventTable inventTable;

    if (itemId)
    {
        inventTable = InventTable::find(itemId);

        if (!inventTable)
        {
            throw error(strfmt(InventTable::txtNotExist(),itemId));
        }
    }

    if (inventDimId && !inventDim)
    {
        inventDim = InventDim::find(inventDimId);
    }

    if (!inventUnitId)
    {
        inventUnitId = inventTable.inventUnitId();
    }

    if (!calcDate)
    {
        calcDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    }
}

protected void initProgressBar()
{
    #macrolib.aviFiles

    progressBar = new RunbaseProgress(1, null);
    progressBar.setCaption("@SYS13118");
}

public void new()
{
    lineNum                 = 0;
    globalLineNum           = 0;
    mapTotalItemConsumption = new Map(Types::String, Types::Real);
    existTradeAgreements    = false;
    useStandardQty          = false;

    progressTotals          = 0;
    progressBar             = null;

    overrideGroupWarnings   = NoYes::No;
}

public TransDate parmCalcDate(TransDate _calcDate = calcDate)
{
    calcDate = _calcDate;
    return calcDate;
}

public boolean parmExistTradeAgreements(boolean _existTradeAgreements = existTradeAgreements)
{
    existTradeAgreements = _existTradeAgreements;
    return existTradeAgreements;
}

public InventDim parmInventDim(InventDim _inventDim = inventDim)
{
    inventDim = _inventDim;
    return inventDim;
}

public InventDimId parmInventDimId(InventDimId _inventDimId = inventDimId)
{
    inventDimId = _inventDimId;
    return inventDimId;
}

public InventTable parmInventTable(InventTable _inventTable = InventTable::find(itemId))
{
    itemId = _inventTable.ItemId;

    if (!prmisdefault(_inventTable))
    {
        skipInventTablevalidation = true;
    }
    if (!_inventTable)
    {
        skipInventTablevalidation = false;
    }

    return _inventTable;
}

public InventUnitId parmInventUnitId(InventUnitId _inventUnitId = inventUnitId)
{
    inventUnitId = _inventUnitId;
    return inventUnitId;
}

public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}

public RunbaseProgress parmProgressBar(RunbaseProgress _progressBar = progressBar)
{
    progressBar = _progressBar;
    return progressBar;
}

public Qty parmSeriesSize(Qty _seriesSize = seriesSize)
{
    seriesSize = _seriesSize;
    return seriesSize;
}

public boolean parmShowProgress(boolean _showProgress = showProgress)
{
    showProgress = _showProgress;
    return showProgress;
}

public void setLineNum()
{
    lineNum = this.getLineNum();
}

public void setProgressTotals()
{
    progressBar.setTotal(progressTotals);
}

public void updateProgress()
{
    if (!progressBar)
    {
        return;
    }

    progressBar.setText(strFmt("@SYS24300",itemId));

    progressBar.incCount();
}

public boolean validate()
{
    if (!itemId)
    {
        return checkFailed("@SYS25157");
    }

    return true;
}

public static ClassDescription description()
{
    return "@SYS343262";
}
